<?php
namespace App\Modules\Sales\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Customers\Domain\Models\CustomerProfile;use App\Modules\Finance\Domain\Models\FinancialAccount;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\SalesOrder;use App\Modules\Pricing\Domain\Models\PriceList;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class CreateSaleController extends Controller {public function __invoke(Request $request):Response{abort_unless($request->user()->hasPermission('sales.create'),403);$customers=CustomerProfile::query()->with('person:id,name')->where('is_active',true)->get()->map(fn($c)=>['id'=>$c->id,'person_id'=>$c->person_id,'name'=>$c->person->name,'default_price_list_id'=>$c->default_price_list_id]);$lists=PriceList::query()->with(['items.presentation.item:id,name'])->where('is_active',true)->get()->map(fn($l)=>['id'=>$l->id,'name'=>$l->name,'is_default'=>$l->is_default,'items'=>$l->items->map(fn($i)=>['presentation_id'=>$i->presentation_id,'product'=>"{$i->presentation->item->name} — {$i->presentation->name} ({$i->presentation->sku})",'price'=>$i->price,'minimum_price'=>$i->minimum_price])]);$orders=SalesOrder::query()->with(['customer.customerProfile','lines.presentation.item:id,name'])->whereIn('status',[SalesOrderStatus::Ready,SalesOrderStatus::PendingProduction,SalesOrderStatus::InProduction])->get()->map(fn($o)=>['id'=>$o->id,'document_number'=>$o->document_number,'customer_profile_id'=>$o->customer->customerProfile?->id,'price_list_id'=>$o->price_list_id,'lines'=>$o->lines->filter(fn($l)=>bccomp($l->ordered_quantity,$l->delivered_quantity,6)>0)->map(fn($l)=>['sales_order_line_id'=>$l->id,'presentation_id'=>$l->presentation_id,'product'=>"{$l->presentation->item->name} — {$l->presentation->name}",'quantity'=>bcsub($l->ordered_quantity,$l->delivered_quantity,6),'unit_price'=>$l->unit_price,'discount'=>0,'price_reason'=>$l->price_reason])]);return Inertia::render('sales/Create',['customers'=>$customers,'priceLists'=>$lists,'orders'=>$orders,'accounts'=>FinancialAccount::query()->where('accepts_payments',true)->where('is_active',true)->get(['id','name','code']),'now'=>now()->format('Y-m-d\TH:i')]);}}
